        while ((remaining.len > 0)) {
            if (std.mem.indexOf(u8, remaining, needle)) |index| {
                _ = &index;
                remaining = remaining[(index + needle.len)..];
                count = (count + 1);
            } else {
                break;
            }
        }
        return (input.len + (count * (replacement.len -| needle.len)));
}

